long fact(int n) {
  if (n <= 1) return 1;          // base case
  return n * fact(n - 1);        // recursive case
}

long fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }   // O(2^n)

double power(double x, int n) {
  if (n == 0) return 1;
  double h = power(x, n / 2);
  return (n % 2) ? h * h * x : h * h;       // O(log n)
}

void hanoi(int n, char from, char to, char via) {
  if (n == 0) return;
  hanoi(n - 1, from, via, to);
  printf("move disk %d %c -> %c\n", n, from, to);
  hanoi(n - 1, via, to, from);
}

void subsets(int i, int n, int path[], int len) {
  if (i == n) { print(path, len); return; }
  subsets(i + 1, n, path, len);              // exclude i
  path[len] = i; subsets(i + 1, n, path, len + 1);   // include i
}
